SELECT jsonb_build_object('customer',(SELECT count(*) FROM app.customer_profiles WHERE id='e2532f1c-c9bc-5674-b904-65afe45b0820'),'command',(SELECT count(*) FROM platform.runtime_command_receipt WHERE id IN ('57f2038d-9c88-53aa-9021-f3d7f6d96d4b','0df06342-5f7e-58c1-9112-e3e2ba4ecbf3')), 'history',(SELECT count(*) FROM app.customer_profile_lifecycle_event WHERE customer_profile_id='e2532f1c-c9bc-5674-b904-65afe45b0820'),'evidence',(SELECT count(*) FROM platform.owner_mutation_evidence WHERE aggregate_kind='CustomerProfile' AND aggregate_id='e2532f1c-c9bc-5674-b904-65afe45b0820'),'outbox',(SELECT count(*) FROM platform.runtime_outbox_message WHERE command_receipt_id IN ('57f2038d-9c88-53aa-9021-f3d7f6d96d4b','0df06342-5f7e-58c1-9112-e3e2ba4ecbf3')),'track_enrollments',(SELECT count(*) FROM app.track_enrollment_receipt WHERE profile_id='e2532f1c-c9bc-5674-b904-65afe45b0820'),'coherent',EXISTS(SELECT 1 FROM app.customer_profiles c
 JOIN platform.runtime_command_receipt q ON q.id='57f2038d-9c88-53aa-9021-f3d7f6d96d4b' AND q.owner_module_id='customer_buyer_profile' AND q.operation='SH-004.v1'
  AND q.subject_scope='CustomerProfile:'||c.id::text AND q.semantic_key='customer-controls-lease-revoke-app-positive' AND q.fingerprint='91b2f9d1c89a6782512d1369a6cf7a278a2678e75e96db10597744261f1cf5e8'
  AND q.state='committed' AND q.source_revision=0 AND q.result_schema_id='SH-004.v1#/$defs/response' AND q.result_schema_version='1'
  AND q.result_body='{"contract":"SH-004.v1","requestId":"lease-revoke-app-positive","status":"ok","value":{"customerProfileId":"e2532f1c-c9bc-5674-b904-65afe45b0820","userId":"696f0d79-8baa-5e8c-a188-19547807a7ea","lifecycle":"active","sourceToken":"0","receipt":{"owner":"customer_buyer_profile","id":"57f2038d-9c88-53aa-9021-f3d7f6d96d4b","semanticKey":"customer-controls-lease-revoke-app-positive","fingerprint":"91b2f9d1c89a6782512d1369a6cf7a278a2678e75e96db10597744261f1cf5e8","sourceToken":"0","recordedAt":"2026-11-17T00:00:00Z"}}}'::jsonb AND q.result_digest=encode(sha256(convert_to(q.result_body::text,'UTF8')),'hex')
 JOIN app.customer_profile_lifecycle_event h ON h.id='d6f7d3f0-98fd-5bb4-82c9-1120eb1f8ca1' AND h.customer_profile_id=c.id AND h.command_receipt_id=q.id
  AND h.source_revision=0 AND h.from_status IS NULL AND h.to_status=c.status AND h.actor_user_id=c.user_id AND h.name='customer.lifecycle_changed.v1'
 JOIN platform.owner_mutation_evidence e ON e.id='566db792-a0c2-523f-8e49-54ccfb2ca995' AND e.command_receipt_id=q.id AND e.owner_module_id=q.owner_module_id
  AND e.aggregate_kind='CustomerProfile' AND e.aggregate_id=c.id::text AND e.previous_revision IS NULL AND e.committed_revision=0
  AND e.action=q.operation AND e.decision_ref='customer-controls-v1' AND e.evidence_schema_version='1'
  AND e.evidence_schema_id='urn:workinants:database-review:owner-evidence:v1#/$defs/CustomerProfile'
  AND e.evidence_body='{"schema":"database-owner-evidence.v1","owner":"customer_buyer_profile","model":"CustomerProfile","primaryKey":{"id":"e2532f1c-c9bc-5674-b904-65afe45b0820"},"prior":null,"committed":{"id":"e2532f1c-c9bc-5674-b904-65afe45b0820","userId":"696f0d79-8baa-5e8c-a188-19547807a7ea","status":"active","revision":"0","privacyGeneration":"0"},"decisionRef":"customer-controls-v1"}'::jsonb AND e.evidence_digest=encode(sha256(convert_to(e.evidence_body::text,'UTF8')),'hex')
 WHERE c.id='e2532f1c-c9bc-5674-b904-65afe45b0820' AND c.user_id='696f0d79-8baa-5e8c-a188-19547807a7ea' AND c.status='active' AND c.revision=0 AND c.privacy_generation=0
  AND c.display_name IS NULL AND c.avatar_media_id IS NULL AND c.city IS NULL AND c.state IS NULL AND c.country IS NULL AND c.archived_at IS NULL
