   AND o.payload_hash=encode(sha256(convert_to(o.payload::text,'UTF8')),'hex')
   AND ((o.id='c8f58aa9-3d23-5da6-8c9b-dc8a28dd5337' AND o.ordinal=0 AND o.kind='event' AND o.name='customer.lifecycle_changed.v1'
    AND o.payload_schema_id='urn:workin-ants:types:v1#/$defs/EventPayload_customer_lifecycle_changed_v1' AND o.payload='{"eventName":"customer.lifecycle_changed.v1","customerProfileId":"e2532f1c-c9bc-5674-b904-65afe45b0820","userId":"696f0d79-8baa-5e8c-a188-19547807a7ea","lifecycleRevision":"0","safeState":"active"}'::jsonb)
    OR (o.id='42a18b05-7dcb-5d45-bcb3-91bf9f214853' AND o.ordinal=1 AND o.kind='command' AND o.name='assignDefaultFreeTrack.v1'
    AND o.payload_schema_id='urn:workinants:database-review:foundation-payloads:v1#/$defs/assignDefaultFreeTrackCustomerCommand' AND o.payload='{"sourceOwner":"customer_buyer_profile","userId":"696f0d79-8baa-5e8c-a188-19547807a7ea","track":"customer","customerProfileId":"e2532f1c-c9bc-5674-b904-65afe45b0820","sourceCreationRevision":"0","sourceCreationReceipt":"57f2038d-9c88-53aa-9021-f3d7f6d96d4b","semanticKey":"customer_buyer_profile/e2532f1c-c9bc-5674-b904-65afe45b0820/default-free-enrollment/v1"}'::jsonb)))=2));
